import pandas as pd
import numpy as np

class MultiTimeframeTradingStrategy:
    def __init__(self, data):
        self.data = data
        self.indicators = self.calculate_indicators()
        self.entry_rules = self.check_entry_rules()
        self.exit_rules = self.check_exit_rules()

    def calculate_indicators(self):
        # Calculate Bollinger Bands
        self.data['bb_middle'] = self.data['Close'].rolling(window=20).mean()
        self.data['bb_upper'] = self.data['bb_middle'] + 2 * self.data['Close'].rolling(window=20).std()
        self.data['bb_lower'] = self.data['bb_middle'] - 2 * self.data['Close'].rolling(window=20).std()

        # Calculate On Balance Volume (OBV)
        self.data['obv'] = np.where(self.data['Close'] > self.data['Close'].shift(1), self.data['Volume'], -self.data['Volume'])
        self.data['obv_ma'] = self.data['obv'].rolling(window=14).mean()

        # Calculate Money Flow Index (MFI)
        self.data['mfi'] = self.calculate_mfi()

        # Calculate Moving Average (MA)
        self.data['ma'] = self.data['Close'].rolling(window=50).mean()

        return {
            'Bollinger Bands': {
                'upper': self.data['bb_upper'],
                'lower': self.data['bb_lower']
            },
            'OBV': {
                'obv': self.data['obv'],
                'obv_ma': self.data['obv_ma']
            },
            'MFI': self.data['mfi'],
            'MA': self.data['ma']
        }

    def calculate_mfi(self):
        high_low = self.data['High'] - self.data['Low']
        high_close = np.abs(self.data['High'] - self.data['Close'].shift(1))
        low_close = np.abs(self.data['Low'] - self.data['Close'].shift(1))
        ranges = pd.concat([high_low, high_close, low_close], axis=1)
        true_range = ranges.max(axis=1)
        df = pd.DataFrame({
            'high': self.data['High'],
            'low': self.data['Low'],
            'close': self.data['Close'],
            'volume': self.data['Volume'],
            'true_range': true_range
        })
        df['money_flow'] = np.where(df['close'] > df['close'].shift(1), df['true_range'] * df['volume'], -df['true_range'] * df['volume'])
        df['mfi'] = df['money_flow'].rolling(window=14).sum() / df['true_range'].rolling(window=14).sum()
        return df['mfi']

    def check_entry_rules(self):
        long_entries = []
        short_entries = []
        for i in range(len(self.data)):
            if self.data['Close'].iloc[i] < self.indicators['Bollinger Bands']['lower'].iloc[i] and self.data['obv'].iloc[i] > self.indicators['OBV']['obv_ma'].iloc[i] and self.indicators['MFI'].iloc[i] < 20:
                long_entries.append(i)
            elif self.data['Close'].iloc[i] > self.indicators['Bollinger Bands']['upper'].iloc[i] and self.data['obv'].iloc[i] < self.indicators['OBV']['obv_ma'].iloc[i] and self.indicators['MFI'].iloc[i] > 80:
                short_entries.append(i)
        return {
            'long': long_entries,
            'short': short_entries
        }

    def check_exit_rules(self):
        long_exits = []
        short_exits = []
        for i in range(len(self.data)):
            if self.data['Close'].iloc[i] > self.indicators['Bollinger Bands']['upper'].iloc[i] and self.data['Close'].iloc[i] > self.indicators['MA'].iloc[i]:
                long_exits.append(i)
            elif self.data['Close'].iloc[i] < self.indicators['Bollinger Bands']['lower'].iloc[i] and self.data['Close'].iloc[i] < self.indicators['MA'].iloc[i]:
                short_exits.append(i)
        return {
            'long': long_exits,
            'short': short_exits
        }

